
CREATE TABLE agencias (
  agencia_id INTEGER PRIMARY KEY, nome TEXT NOT NULL, cidade TEXT NOT NULL, uf CHAR(2) NOT NULL
);
CREATE TABLE clientes (
  cliente_id INTEGER PRIMARY KEY, nome TEXT NOT NULL, cidade TEXT NOT NULL, uf CHAR(2) NOT NULL,
  telefone TEXT, renda_mensal NUMERIC(12,2) NOT NULL, data_cadastro DATE NOT NULL,
  agencia_id INTEGER NOT NULL REFERENCES agencias
);
CREATE TABLE contratos (
  contrato_id INTEGER PRIMARY KEY, cliente_id INTEGER NOT NULL REFERENCES clientes,
  agencia_id INTEGER NOT NULL REFERENCES agencias, produto TEXT NOT NULL,
  valor_emprestado NUMERIC(12,2) NOT NULL, taxa_mensal NUMERIC(5,2) NOT NULL,
  qtd_parcelas INTEGER NOT NULL, data_inicio DATE NOT NULL, status TEXT NOT NULL
);
CREATE TABLE parcelas (
  parcela_id INTEGER PRIMARY KEY, contrato_id INTEGER NOT NULL REFERENCES contratos,
  numero INTEGER NOT NULL, data_vencimento DATE NOT NULL, valor NUMERIC(12,2) NOT NULL
);
CREATE TABLE pagamentos (
  pagamento_id INTEGER PRIMARY KEY, parcela_id INTEGER NOT NULL REFERENCES parcelas,
  data_pagamento DATE NOT NULL, valor_pago NUMERIC(12,2) NOT NULL, canal TEXT NOT NULL
);
CREATE TABLE pagamentos_brutos (
  evento_id INTEGER PRIMARY KEY, parcela_id INTEGER NOT NULL, data_pagamento DATE NOT NULL,
  valor_pago NUMERIC(12,2) NOT NULL, canal TEXT NOT NULL, importado_em TIMESTAMP NOT NULL
);

